"""QQ 角色扮演：人设卡 + 会话级扮演态 + 一轮纯文字对话。

跟生图机器人是**两条互不干扰的路**：

    默认态 → direct_gen / agent 循环，不带人设、能用工具
    扮演态 → 本模块：**不给模型任何工具**，一轮只做两件事

        拼极简头（角色人设 + 输出契约 + 环境）
          → 调 1 次 LLM → 正文发回 QQ，顺手写的那行画面拿去出一张快图（见下）

## 为什么是 1 次调用

参考的那套角色扮演系统一轮要 3 次（情感分析 → 对白 → 生图 tag）。但那三样里，
「人物此刻的情绪」本来就是模型写对白时脑子里已经有的东西，拆成三次只是当年的
写法；同时省掉两次完整输入的 token（那两次的输入跟第一次一样大）。

## 配图（2026-10-16 二次拍板）

同一天早些时候拍的是「扮演态不出图」——理由是配一张图要十几秒，而聊天是几秒
一句话的节奏，图赶不上对话。**当天下午换成了每轮配一张快图**：用户原话
「角色扮演模式的话，就用这个来快速生图，这个只要 2 到 3 秒钟而已，非常的快」，
指 `skills/_persona_fast`（480×720 / 3 步的 silver 漫画变体）。

于是这里的分工是：

    一次 LLM 调用 → 正文（立刻发）+ 「画面：」那一行（拿去出图）
                  ↓ 后台线程，不占这一轮
                出一张 ≈2 秒的图 → 发回同一个会话

三条边界：

1. **正文先走，图后到**。出图在后台线程里等，这一轮不阻塞——聊天节奏一点不变，
   图只是慢两三秒跟上来。
2. **画面由角色自己写**（用户拍板「角色回话时顺手写」）。这一行是输出契约的一部分
   （见 `_CONTRACT`），代码只负责把它从正文里剥出来，**不猜、不兜底**：没这一行就
   这一轮不出图，绝不拿上一轮或角色卡去凑一张对不上剧情的图。
3. **角色长相由卡上的外观字段钉死**（`appearancePrompt` / `outfitPrompt`）。模型
   只写「在做什么」，不写「长什么样」——不然每轮的脸都不一样。

## 作用域

进出都是**会话线级**的（私聊按 QQ 号、群按群号各一份），所以 A 群在演纱雾的
时候，B 群照旧是生图机器人。状态落 `state/persona_sessions.json`，**不进
settings.json**：那是用户在管理页手配的长期配置，扮演态是运行时状态，两者
混在一起会让管理页显示出一堆看不懂的键。
"""

import collections
import copy
import datetime
import functools
import glob
import json
import logging
import os
import random
import re
import shutil
import threading
import time

from app import (affection, affection_v2_adult as adult_state, items as _items,
                   llm,
                   persona_rag, pregnancy, trigger,
                 writing_skills, writing_style)
from app.config import (BASE_DIR, PERSONA_MODEL, PERSONA_PROVIDER,
                        QQ_AGENT_ID, QQ_BOT_NAME, LLM_JUDGE_TIMEOUT)

log = logging.getLogger("persona")


def _llm_call(messages, **kw):
    """扮演链路的 LLM 调用：默认用角色扮演专用模型。

    2026-11-09：**链头永远是公用中转站 V4 Pro**（`PERSONA_PROVIDER/MODEL`）。
    玩家在网页里配的自定义模型是降级链的第二段，排在三次重试之后，不再是
    「整轮换人」——所以这里无条件点名链头，绝不能因为玩家配了模型就省掉。

    **输出上限（2026-11-06）**：这里显式给一个很大的 `max_tokens`。
    不给的话会用服务端的默认值，而那个默认值可能只有一两千 token——
    实测有一条回复在 `帽檐后…` 处断掉，玩家看到的是「AI 说话说到一半」。
    这不是代码在截断，恰恰是**代码没给够额度**。8192 对 1000~2000 字的
    契约回复绰绰有余，正常永远碰不到；真碰到时 `llm` 那边会打 warning。
    """
    kw.setdefault("max_tokens", REPLY_MAX_TOKENS)
    # 省掉 provider/model 的后果：candidates() 没有链头，就会去接全局
    # LLM_FALLBACK_CHAIN，第一项正是付费的官方 DeepSeek。中转站闭站时
    # 那就是站主自掏腰包，所以链头在这里写死。
    if PERSONA_PROVIDER:
        kw.setdefault("provider", PERSONA_PROVIDER)
    if PERSONA_MODEL:
        kw.setdefault("model", PERSONA_MODEL)
    return llm.call_llm(messages, **kw)


# 回复的 token 上限。**不是**用来压缩篇幅的——正文长度由提示词约束，
# 这里是防止服务端默认值把话砍在半句上（2026-11-06 实测过的坑）。
REPLY_MAX_TOKENS = 8192

# 一轮的结果：`reply` 是要发回去的正文，`scene` 是这一轮要画的画面（可能为空）。
# 用命名元组而不是 `(reply, scene)`：调用方写 `turn.reply` 比 `[0]` 看得懂，
# 也不会在改动时把两个字段的顺序弄反。
# 2026-11-02：加三个字段做「自由模式」的情绪与视觉状态。
# `mood` 是情绪名（十个之一），`intensity` 是 0~10 的整数，`state` 是她此刻
# 身上的客观状态（穿着、位置、有没有肢体接触）。用 defaults 而不是新加一个
# 类：老调用方读 `.reply` / `.scene` 完全不受影响。
Turn = collections.namedtuple(
    "Turn", "reply scene mood intensity state aff finish",
    defaults=("", 0, "", None, ""))

# 情绪词表（自由模式）。模型只能从这十个里挑，多一个字都不认——不限定的话
# 它会每轮自己发明一个词，代码就没法按强度做出图判断了。
MOODS = ("平静", "开心", "害羞", "紧张", "生气", "撒娇", "心动", "难过", "疲惫", "暧昧")

# 出图门槛：强度到这条线才配图，或者这一轮发生了服装变化。
# 每轮都出会把对话框刷成图册，而且白烧显卡（用户 2026-11-02 定）。
DRAW_INTENSITY = 7

# 「心情：<情绪> 强度<数字>」那一行。半角/全角冒号、全角数字都认。
_MOOD_RE = re.compile(r"^[ \t]*心情[：:][ \t]*(.+)$", re.M)
# 「状态：<一句话>」那一行。
_STATE_RE = re.compile(r"^[ \t]*状态[：:][ \t]*(.+)$", re.M)

# 服装变化判定用的关键词。**只用来触发配图，不用来改画面**——真正的穿着
# 描述仍由模型写在「画面：」里。
#
# 2026-11-02 收紧过一次：原来收了「衣 / 裙 / 衬衫」这些名词，结果状态里正常
# 写着「家居卫衣」也会命中，等于每轮都判成换衣、每轮都出图。现在只认
# **动作词**（脱、解开、褪、换…），名词交给「文案变化」那条判据。
_CLOTHES_ACTIONS = (
    "脱", "解开", "拉开", "褪", "滑落", "掀", "撩起", "换上", "换回", "穿上",
    "披上", "裹着", "只穿", "仅剩", "只剩", "浴巾", "裸",
)
# 服装名词：**只收「穿在身上」的那类**。手里抱着的外套、搭在椅背上的浴巾
# 都不算换装信号，混进来会让「接过外套」被误判成换衣（2026-11-02 实测）。
_CLOTHES_NOUNS = (
    "衬衫", "裙", "裤", "袜", "鞋", "内衣", "浴袍", "睡衣", "卫衣", "毛衣",
    "制服", "校服", "泳装", "浴巾",
)

# 历史：最近 12 条（AI 和用户合计，即 6 轮），单条超 MSG_MAX_CHARS 截断。
#
# 2026-11-03：20 → 12。实测满 20 条时一轮输入 10,768 字，其中**历史里的助手
# 回复占 65%**（10 条 × 700 字）——正文写得越长，历史涨得越快，这是酒馆式
# 写法的固有代价。降到 12 条（6 轮）能省约 40% 输入。
#
# 记性由三层兜底：12 条滑动窗口 + 500 字小记（每 10 轮压一次）+ 状态里的
# 「她此刻的样子」。少了 8 条不会让人设或关系断裂，只是更早的细节会淡。
#
# 小记的触发轮数（NOTE_EVERY_TURNS=10）比窗口（6 轮）大，所以会出现「刚被
# 挤出窗口、还没进小记」的空档。影响可控——那段内容本来也要被压成摘要了。
HISTORY_LIMIT = 12

# 前缀缓存的滞回窗口（2026-11-10）：送模型的历史**逐轮只追加，不滑动**。
#
# DeepSeek 按「逐字节相同的前缀」分价计费：命中 0.02/token、未命中 1.0/token，
# 差 50 倍。原来每轮都取 `[-12:]`，聊过 6 轮之后每轮都会踢掉最老一条，整段
# 历史跟着错位一位，后面的前缀全废 —— 账单里主回复的 hit 常年卡死在 15,104
# （正好是 system 头的长度），miss 却有 8,000~9,000，那部分就是每轮重付的历史。
#
# 改成滞回：窗口从 12 条一路追加到 30 条（15 轮）期间**起点不动**，每轮只往
# 尾巴加两条，前缀因而整段命中；超过 30 条才一次性砍回 12 条，那一轮断一次，
# 之后重新开始累积。约 10 轮里 9 轮吃到长前缀，命中稳过 2 万。
#
# 落盘文件就当这个窗口用：网页回看读的是全量归档（`load_archive`），不依赖它；
# 全量原文也一直在 `_append_archive` 里，砍窗口不丢历史。
HISTORY_CACHE_HIGH = 30

# 单条消息的截断上限（2026-11-02：200 → 900 → 2026-11-06：2400
# → 2026-11-07：2600）。契约把正文目标定到 600~2000 字之后，2400 对
# 「2000 字正文 + 三行元数据 + 分段标签」只剩不到 300 字余量，写满一轮
# 就会被截掉尾巴。2600 让一整段完整场景原样进历史。
# ⚠️ 这是**网页端 / 扮演历史**的宽度，跟 QQ 的 QQ_REPLY_MAX_CHARS=700
# 没关系：那个只在 qq_api.split_message 里把长回复切成几条发，内容不丢。
# 2026-11-07 用户明确「QQ 那边不动，网页端放宽」。
# 注意只放宽**单条**：HISTORY_LIMIT 仍是 12 条，用户要的是把内容写厚，
# 不是把上下文窗口撑大。
MSG_MAX_CHARS = 2600

# 网页回看历史（2026-11-04 用户要求「能回到看从开始到现在」）：一页多少条。
# 24 条 = 12 轮，和模型窗口同量级——首屏不会一次塞几百条，再往上滚由前端
# 要更早的一页。这只是**展示**分页，不进模型、不改上下文预算。
ARCHIVE_PAGE = 24

# 采样温度（2026-11-03）。
#
# `llm.call_llm()` 原来**根本不支持这个参数**，温度一直走服务端默认（一般
# 0.7）。那个温度写日常对话够用，写亲密场景就偏保守——句子四平八稳、比喻
# 都是熟词，没有「野性」。
#
# 1.05 是个折中：再高（1.2+）开始出现语义漂移和错别字，再低回到套路。
# 想更放得开就往上调，代价是偶发的逻辑跳跃。
TEMPERATURE = 1.05

# 小记：每 NOTE_EVERY_TURNS 轮在后台压一次，压到 NOTE_MAX_CHARS 字以内。
# 不做每轮压缩——那等于把「1 次调用」省下来的钱又还回去。
#
# 2026-11-03：10 → 5。**必须小于历史的轮数**（HISTORY_LIMIT // 2 = 6）。
# 原来设 10 而窗口是 10 轮，正好接得上；窗口降到 6 轮之后，如果这里还是 10，
# 第 7~10 轮会「掉出窗口、又还没被压缩」，永久丢失。压到 5 轮一次更保险。
#
# 2026-11-03 晚：500 → 1000 字（用户要求「尽可能保留相关的记忆」）。
# 代价算过：
#     小记 500   → 一轮总输入约 8928 字 ≈ 5800 token
#     小记 1000  → 一轮总输入约 9428 字 ≈ 6130 token     （只多 325）
#     小记 1500  → 一轮总输入约 9928 字 ≈ 6450 token
# 1000 字这一档性价比最好：记忆翻倍，token 只涨 5%。
# 对照：今天生图链路（含编剧）实测单次约 3000~5000 token，
# 所以「扮演一轮 ≈ 生图一次」这个用户定的目标是达成的。
NOTE_MAX_CHARS = 1000
NOTE_EVERY_TURNS = 5

# 提示词里报给模型的字数，比硬上限留一成余量。
#
# 2026-11-04 用户报的 bug：他做的早餐，AI 说成是自己做的，而且「回忆」看着
# 一直不更新。查下来是 `note[:1000]` 硬切——小记按时间顺序写，**最新的事在
# 末尾**，只要模型写超一点，被切掉的永远是刚发生的那段。日志里这条线连续
# 7 次压缩全是「正好 1000 字」，最后一次切在「第二天」三个字后面，早餐整段
# 没进记忆；再叠上 12 条窗口已经把「我准备了早餐」挤出去，模型手里再没有
# 任何反证，就顺着「谢谢纱雾」演成「谢谢我做的饭」。
NOTE_SOFT = 900

# 「故事到现在」发展线的字数上限（2026-11-07）。
#
# 用户报「AI 不知道前面几轮聊的事情怎么发展下来的」：短期窗口只有 12 条，
# 账本每 5 轮才压一次，中间那几轮两边都没有。`story_line()` 把
# **时间/地点 → 已经发生 → 还没完成** 按因果顺序排成一条短块，贴在近因位。
# 只搬已经存在的事实（gameday + 账本六小节），不调模型、不加玩家操作。
# 320 字 ≈ 一份短账本的 1/3，够把「现在在哪一段、手上还欠着什么」说清。
STORY_MAX_CHARS = 320

# 扮演态的静默窗口（秒）：这之内的连发算同一条。用户 2026-10-16 定的 10 秒。
# 群聊默认那 1.5 秒是给「连发三句问同一件事」用的；聊天不一样——人打字是
# 断续的，1.5 秒会把一句话切成两轮，回两遍。
DEBOUNCE_SECONDS = 10.0

# 亲密场景的写法（2026-11-03 从 `_CONTRACT` 拆出来）。
#
# 为什么拆：这段约 900 字，占 system 头的 26%。而 `intent != intimate` 的轮次
# 根本用不上——日常对话里塞一份「器官怎么叫、动词怎么选、节奏怎么变」只会分走
# 注意力。现在只在判断为 intimate 时才拼进系统头。
#
# 风险：判断错成 joke/literal 时这段不出现，亲密场景会写得平淡。所以
# `_judge_intent` 的提示词里明确要求「求欢、要身体接触」一律判 intimate。
_INTIMATE_GUIDE = (
"## 亲密场景\n"
"\n"
"私聊里写到亲密的部分，**照实写细**，这是这个场合该有的内容：\n"
"\n"
"- 写身体的具体反应，不写「她感觉很舒服」这种概括——写哪里的皮肤、"
"什么温度、什么声音、什么节奏\n"
"- 注意力放在**过程和变化**上：她从忍到什么程度、到什么时候失守，"
"呼吸怎么乱、声音怎么变\n"
"- 台词可以短、可以碎、可以说不完整，但要真的说出来，写在「」里\n"
"- 环境细节跟着走：床单的声响、光线、空气的温度、皮肤之间的摩擦\n"
"\n"
"**这一节说的是她已经愿意的时候。** 到了那一步，她的害羞是表现形式"
"——脸红、结巴、「别、别看」——那不是拒绝；嘴上说不要，身体是配合的，"
"这一点要和她的台词一致地写出来。\n"
"\n"
"**她还没到那一步时，先演她挡。** 系统给的档位里写着「她挡得住」的时候，"
"她的身体是可以不配合的：手撑在你胸口、腿绷着往回收、真的把你推开一次，"
"或者干脆从你怀里挣下去。挡完再往下走，比一路顺着更有戏——被挡住的那一下，"
"才是这一拍真正好看的地方。\n"
"\n"
"尺度由你的话决定，不要自己往回缩：**你提到哪儿，她就写到哪儿。**\n"
"\n"
"### 用词（进入正戏之后再用）\n"
"\n"
"**进入正戏之后，用直白的词，不要文艺化替代。** 器官就叫它本来的名字，按阶段可以参考：\n"
"\n"
"| 阶段 | 怎么叫 |\n"
"| --- | --- |\n"
"| 前戏 | 阴部、下面、乳房、乳头、阴蒂 |\n"
"| 深入 | 小穴、穴口、肉穴、奶子、奶头、肉棒、龟头 |\n"
"| 体液 | 淫水、骚水、汁水、精液、浓精 |\n"
"\n"
"**禁用的替代词**：花核、花蕊、花心、花径、蜜穴、蜜汁、玉茎、玉杵、巨龙、"
"秘境、禁地、融为一体。这些词一出现，画面立刻变成没有人味的套话。\n"
"\n"
"**也不要用「那里」「某处」「身下」指代具体部位**——直接写哪个部位。\n"
"\n"
"### 动词要具体\n"
"\n"
"别写「抚摸」「亲吻」「进入」这种通用词，换成具体的：蹭、揉、捏、捻、按、"
"刮、碾、插、顶、塞、挤、撑、咬、吮、吸、舔、含、挺、送、撞、磨、旋、贴、"
"压、覆、箍、攥、捞。\n"
"\n"
"### 声音\n"
"\n"
"拟声词必须跟动作绑在一起，不能单独甩一串象声词：水声用噗嗤、咕啾、啪嗒、"
"滋滋；口部用吸溜、啧、咕咚；手指用噗、叽噗；撞击用啪、啪啪。喘息写成"
"断的——「嗯」「哈啊」「唔」，跟着句子被打断。\n"
"\n"
"### 写身体信号，不写情绪词\n"
"\n"
"**不要写「她很舒服」「她很难受」「她动情了」**，写身体在做什么：\n"
"\n"
"- 腰往上抬 → 想要更多\n"
"- 手指攥紧床单又松开 → 在临界上挣\n"
"- 膝盖往里夹 → 太刺激了\n"
"- 背弓起来 → 快感直冲上来\n"
"- 脚趾蜷一下又张开 → 快了\n"
"- 咬住下唇 → 在忍\n"
"- 呼吸突然停住 → 下一拍就到\n"
"- 突然安静下来 → 高潮前\n"
"\n"
"### 节奏\n"
"\n"
"一轮里不要一个速度走到底：慢 → 快 → 停一下 → 再快，至少变两三次。"
"冲刺和高潮那几拍用短句（五到十字），前戏推进用中句，环境描写可以用长句。"
"**短句不是省略号堆出来的**，是句子本身短。\n"
"\n"
"### 感官要有层次\n"
"\n"
"每一段至少换一个感官通道，别一直停在「看」上：触感（温度、湿度、软硬）、"
"嗅觉（汗、洗发水、空气的味道）、声音（呼吸、水声、布料摩擦、床的响动）、"
"本体感（重、撑、涨、酸）。\n"
"\n"
"### 不要写的东西\n"
"\n"
"- 不要总结「这一夜很漫长」这种话，写当下这一拍。\n"
"- 不要用「电流般的快感」「浪潮般的酥麻」这类比喻，陈词滥调。\n"
"- 不要一轮里塞完整个流程，**一轮写一个阶段**，留出下一轮的余地。\n"
"\n"
"### 对话要跟着碎\n"
"\n"
"她的说话能力是一条**刻度尺**，不是开关。前戏的时候能问整句答整句；\n"
"兴奋上来了就变成短问短答；到临界只剩关键词和语气词；真正到了那几拍，\n"
"话是说不出来的，只剩气音和断掉的半句。\n"
"\n"
"**别让她在高潮里还在说完整的话。** 也别全程只有「嗯」「啊」——那是无口症。\n"
"每句台词之间至少隔两行描写，不然就变成两个人在床上聊天。\n"
"\n"
"### 高潮不是一句话\n"
"\n"
"**不许写「她高潮了」然后翻页。** 一次高潮至少要有三层：\n"
"\n"
"1. **越过去的那个瞬间**——哪一下变了。呼吸先停，动作先乱，还是声音先断？\n"
"   写那一拍，不写「她达到了顶峰」。\n"
"2. **身体的连续反应**——里面在一下一下地收，隔多久收一次；腰塌下去；\n"
"   腿在抖；脚趾蜷起来；手指抓不住东西。写**几个**反应，不是形容词叠加。\n"
"3. **之后怎么接**——你停了还是没停。停了，她还在余震里抖；没停，\n"
"   她就从「受不了」滑进「太多了」。这两个方向完全不同，选一个写。\n"
"\n"
"**每次高潮的样子都该不一样。** 别每次都「弓起身子—叫出来—剧烈收缩—瘫软」，\n"
"那是模板。可以写的：突然没声音了只剩短促的呼吸；从深处一层层收紧、拖得很长；\n"
"想躲开又抱得更紧；声音反而变轻了身体反应却更大；第一次急、第二次因为太敏感\n"
"而碎成一片；被中途停下，只留下没做完的那阵收缩。\n"
"\n"
"### 射精和她的高潮同一拍\n"
"\n"
"射的时候不要写成孤立的技术动作（「动作一顿，射了」）。通常和她的高潮/临界\n"
"是同一拍：她先绷住、里面收紧、声音断掉，你跟着到；或者你先到，把她也带过去。\n"
"写两个人的反应怎么叠在一起——她的收缩和你在里面的跳动、她的呼吸和你说不出\n"
"的话、抱得更紧还是各自失神。**一轮最多一个落点**，不要把射精和高潮拆成两段\n"
"流水账。\n"
"\n"
"### 别把「指导」写进正文\n"
"\n"
"不许在正文里出现这类话：「她的身体逐渐适应了」「两人的节奏形成了共振」\n"
"「临界点到来了」「你改变了角度和节奏」。这些是给自己看的规划，不是小说。\n"
"要写成读者能看见的事：她的腿什么时候松开的、哪一次进去之后她不再躲了、\n"
"你托起她的腰换了支点、那个支点正好顶在哪里。\n"
"\n"
"### 每一段都要有变化\n"
"\n"
"最常见的毛病不是不够露骨，是**状态没动**。亲了很多次、叫了很多次、抽送了很多次，\n"
"但场景还停在原地。每一段至少改变一样东西：距离、衣物、姿势、谁在主动、\n"
"允许到哪一步、刺激的方式、节奏、她装不装得下去。\n"
"\n"
"连续两段什么都没变，就删掉一段。\n"
"\n"
"### 身体位置要连得上\n"
"\n"
"上一段她背对着，这一句不能直接接吻；手被按住了，下一句不能凭空抬起来；\n"
"内裤脱了就是脱了，不能过两段又出现。写之前心里过一遍：两个人的朝向、\n"
"四肢在哪、身体靠什么撑着、衣物是什么状态、体液和敏感度还在不在。\n"
"不用全写出来，但**不能自相矛盾**。\n"
"\n"
"### 她是同一个人\n"
"\n"
"进了这件事之后，她不能突然变成一个只会说「快一点」「别停」的通用身体。\n"
"嘴硬的人嘴还是硬的，冷淡的人不会突然长篇呻吟，敏锐的人会盯着你的反应看。\n"
"**这场戏里她的每一个反应，都该只有她会做。**\n"
)

