# 接触位置（2026-11-07 位置状态机）。
#
# 玩家实测的乱跳：上一拍还在后庭，下一句直接「射进小穴」；再下一句又「插进
# 嘴里」，中间没有任何退出/进入的动作。根因不是模型笨，是它**没有状态**——
# 300~500 字里它只能盯住当下的动作，跨轮的一致性必须靠外部记。
#
# 状态来源：角色 AI 自己在状态行第五段交（契约里限死七个词）。系统只做归一、
# 存上一拍、在换位置时补一句硬约束。
_CONTACT_LABEL = {"none": "无", "mouth": "口", "pussy": "小穴",
                  "anus": "后庭", "hand": "手", "breast": "胸", "thigh": "腿"}

_CONTACT_ALIAS = [
    ("none", ("无", "没有", "没", "未", "none")),
    ("pussy", ("小穴", "阴道", "穴", "里面", "pussy", "vagina")),
    ("anus", ("后庭", "肛门", "后穴", "anus", "anal")),
    ("mouth", ("口", "嘴", "口腔", "mouth", "oral")),
    ("breast", ("胸", "乳房", "breast")),
    ("thigh", ("腿", "大腿", "thigh")),
    ("hand", ("手", "手指", "hand")),
]


def normalize_contact(value):
    """任意写法 → 七个标准值之一；认不出来返回空串（当作「这一轮没交」）。"""
    raw = str(value or "").strip()
    if not raw:
        return ""
    low = raw.lower()
    for key, words in _CONTACT_ALIAS:
        for w in words:
            if w in low:
                return key
    return ""


def contact_block(gd):
    """当前接触位置 + 换位置约束。只在亲密轮拼。"""
    if not isinstance(gd, dict):
        return ""
    cur = str(gd.get("contact") or "").strip()
    if not cur:
        return ""
    prev = str(gd.get("contact_prev") or "").strip()
    lines = ["## 现在连在哪里",
             "接触：%s" % _CONTACT_LABEL.get(cur, cur)]
    # 换位置 = 上一拍和这一拍都非空、且不同。这时候必须写过渡，否则读者
    # 看到的就是「上一句还在后庭，下一句已经在嘴里」。
    if prev and prev != cur and "none" not in (prev, cur):
        lines.append(
            "⚠ 上一拍还在**%s**，这一拍到了**%s**。"
            "**必须写清怎么退出来、怎么进去**——抽出来、换个姿势、再进，"
            "至少一句话带过。直接从一处跳到另一处，这一轮算穿帮。"
            % (_CONTACT_LABEL.get(prev, prev), _CONTACT_LABEL.get(cur, cur)))
    elif prev == "none" and cur != "none":
        lines.append("这一拍刚进去。**第一次进入要写**，别一句「已经在了」。")
    return "\n".join(lines)


def _pick_level(lst, v):
    """从配置的档位表里挑当前这一档（min 从高到低排好的）。"""
    try:
        v = int(v or 0)
    except (TypeError, ValueError):
        v = 0
    for lv in lst or []:
        if v >= int(lv.get("min") or 0):
            return lv
    return {}


def _combo_hits(aff_res, gd):
    """组合规则命中的那几条（对应全书第 12 节）。

    单轴管不了的事：时间×冲动、位置×高潮、戒备×好感、屈服×高潮。
    命中的用**一句话**点出来，详细写法让模型回全书里看——这里只负责把
    它的注意力拽到对的节上。
    """
    out = []
    try:
        ar = int(aff_res.get("arousal") or 0)
        ex = int(aff_res.get("excite") or 0)
        val = int(aff_res.get("value") or 0)
        sus = int(aff_res.get("suspicion") or 0)
        sub = int(aff_res.get("submit") or 0)
    except (TypeError, ValueError):
        return out
    ph = normalize_phase((gd or {}).get("phase"))
    con = str((gd or {}).get("contact") or "")

    if ph == "深夜":
        if ar < 60:
            out.append("深夜 × 冲动 %d：约不动，别写成欲拒还迎（12.1）" % ar)
        elif ar >= 80:
            out.append("深夜 × 冲动 %d：她不等你开口（12.1）" % ar)
        else:
            out.append("深夜 × 冲动 %d：会答应，但会抱怨、会看时间（12.1）" % ar)
    elif ph == "傍晚" and ar >= 45:
        out.append("傍晚 × 冲动 %d：最容易出事的一组（12.1）" % ar)

    if con == "mouth" and ex >= 75:
        out.append("位置在口 × 高潮 %d：她说不出完整的话（12.2）" % ex)
    elif con in ("pussy", "anus") and ex >= 75:
        if sub < 40:
            out.append("位置在%s × 高潮 %d × 屈服 %d：想叫又忍着（12.2/12.5）"
                       % (_CONTACT_LABEL.get(con, con), ex, sub))
        elif sub > 60:
            out.append("位置在%s × 高潮 %d × 屈服 %d：不装了，叫出来（12.5）"
                       % (_CONTACT_LABEL.get(con, con), ex, sub))
    elif con == "none" and ex >= 75:
        out.append("还没连上 × 高潮 %d：光是碰就快到了（12.2）" % ex)

    if sus > 20 and val < 30:
        out.append("戒备 %d × 好感 %d：越界一次就记账（12.3）" % (sus, val))
    elif sus > 20 and val > 60:
        out.append("戒备 %d × 好感 %d：她防的是失去，不是被伤害（12.3）" % (sus, val))
    elif sus > 30:
        out.append("戒备 %d：身体接触全关，包括牵手（12.3）" % sus)
    return out


def body_state_block(aff_res, gd=None):
    """「你现在在」+ 组合命中（2026-11-07 方案 C）。

    全书（`skills/writing/00-state-guide/state-guide.md`）负责「这一档怎么写」，
    这里只负责两件事：
      1. 报当前数值和档位名——模型拿名字回全书里找同名小节；
      2. 算组合命中——单轴管不了的事，一句话把它拉到第 12 节。
    全书读不到时退回内置的 `_TIME_LAYERS` / `_AROUSAL_LAYERS`（旧路径）。

    只读 `affection.settle()` 的返回值，不碰任何存储。
    """
    if not isinstance(aff_res, dict) or not aff_res.get("active"):
        return ""
    try:
        ex = int(aff_res.get("excite") or 0)
        ar = int(aff_res.get("arousal") or 0)
        val = int(aff_res.get("value") or 0)
        cor = int(aff_res.get("corrupt") or 0)
        sub = int(aff_res.get("submit") or 0)
        sus = int(aff_res.get("suspicion") or 0)
    except (TypeError, ValueError):
        return ""
    try:
        from app import affection
    except Exception:                                     # noqa: BLE001
        return ""
    gd = gd if isinstance(gd, dict) else {}
    ph = normalize_phase(gd.get("phase"))
    tier = affection.tier_for(val) or {}
    al = affection.arousal_level(ar) or {}
    ol = affection.orgasm_level(ex) or {}
    try:
        cfg = affection.load_config()
    except Exception:                                     # noqa: BLE001
        cfg = {}
    cl = _pick_level(cfg.get("corruption_levels"), cor)
    sl = _pick_level(cfg.get("submission_levels"), sub)

    book = writing_skills.state_guide()
    if book:
        lines = ["## 你现在在（回《状态值全书》找同名小节，先看第 12 节）"]
        lines.append("好感 %d（%s）· 感情 %s · 戒备 %d"
                     % (val, tier.get("name") or "—",
                        affection.level_name(aff_res.get("level")) or "—", sus))
        lines.append("冲动 %d（%s）· 高潮 %d（%s）"
                     % (ar, al.get("name") or "—", ex, ol.get("name") or "—"))
        lines.append("堕落 %d（%s）· 屈服 %d（%s）"
                     % (cor, cl.get("name") or "—", sub, sl.get("name") or "—"))
        lines.append("第 %d 天 · %s · 接触：%s"
                     % (_day_of(gd), ph or "时段未定",
                        _CONTACT_LABEL.get(str(gd.get("contact") or ""), "无")))
        hits = _combo_hits(aff_res, gd)
        if hits:
            lines.append("")
            lines.append("【组合命中】")
            lines.extend("- " + h for h in hits)
        con = contact_block(gd)
        if con:
            lines.append("")
            lines.append(con)
        return "\n".join(lines)

    # ── 旧路径：全书读不到时，用内置档位顶上 ──
    lines = ["## 她现在的身体（这一轮就按这个演，数值不要跳）",
             "第 %d 天 · %s" % (_day_of(gd), ph or "时段未定")]
    tlayer = _TIME_LAYERS.get(ph or "")
    if tlayer:
        lines.append(tlayer)
    lines.append("高潮 %d/100 · %s" % (ex, ol.get("name") or "—"))
    lines.append("冲动 %d/100 · %s" % (ar, al.get("name") or "—"))
    layer = _AROUSAL_LAYERS.get(str(al.get("key") or ""))
    if layer:
        lines.append(layer)
    con = contact_block(gd)
    if con:
        lines.append(con)
    return "\n".join(lines)


# 堕落高的时候再加一层：她的反应已经不只是身体的了。
_CORRUPT_LAYER = (
    "### 她现在不一样了\n"
    "\n"
    "这场里她的反应里有一层**她自己也不想要的东西**：身体比嘴先服。\n"
    "她会主动一点，然后被自己吓到；会在中途突然安静，像在跟自己较劲；\n"
    "事后会有一段不说话的空白——不是生气，是不知道该怎么面对刚才那个自己。\n"
    "\n"
    "**别写成「她终于放开了」。** 堕落不是解锁，是往下沉。\n"
    "她越配合，越该有一个瞬间让你看见她其实清楚自己在做什么。\n"
)

# 压迫场（2026-11-05）。和 `_CORRUPT_LAYER` 分工：
#   堕落层管「她的反应里有她不想要的东西」——那条线默认她是被说动的；
#   这一层管「她从头到尾没同意」，快感是加在她身上的，不是她要的。
# 所以这里不再写「她会主动一点」——那句话在这一场里会直接把屈辱写没。
_FORCED_LAYER = (
    "### 这一场是在压迫下发生的\n"
    "\n"
    "**她不是自愿的。** 这个事实不许被任何一句甜腻的描写盖过去：\n"
    "\n"
    "- **嘴和身体分开写**：她说的和身上发生的对不上，这道裂缝就是这一场的看点。\n"
    "- **给一个具体的不愿意**：别过脸、咬着下唇没出声、手推在你胸口但没真的用力——"
    "挑一个写实，别写「她挣扎了一下」。\n"
    "- **不许她求欢**。她可以求你别继续、可以求你快一点结束——那是她的处境，不是她的欲望。\n"
    "- **她的身体反应要让她自己难堪**：湿了、软了、叫出来了，她的第一反应是羞耻，"
    "不是享受。写她想去遮、想咬住、想把声音吞回去。\n"
    "- **事后必须留痕**：躲开、不说话、去洗手、把衣服一件件穿回去，"
    "或者第二天不敢看你。**别写事后温存**——那是另一条线的写法。\n"
)


def intimate_guide(aff_res=None):
    """按当前状态拼出「这一拍该怎么写」那段。

    `aff_res` 是 `affection.settle()` 的返回值；拿不到（自由模式、没开攻略）
    就返回空串——只留 `_INTIMATE_GUIDE` 那段通用写法，不影响正常回话。

    为什么要分层：高潮值 20 和 90 用同一套写法，模型会一路写成同一个调子，
    从「还没起来」直接跳到「到了」，中间那三个档位等于不存在。
    这也是 `skills/writing/` 里反复强调的那条——**每一段都要有变化**。
    """
    if not isinstance(aff_res, dict) or not aff_res.get("active"):
        return ""
    out = []
    ex = int(aff_res.get("excite") or 0)
    if ex > 0:
        # 高潮值的档位 key（cold/awake/rising/edge/over）由 affection 侧算好
        try:
            from app import affection
            lv = affection.orgasm_level(ex) or {}
        except Exception:                                 # noqa: BLE001
            lv = {}
        layer = _ORGASM_LAYERS.get(str(lv.get("key") or ""))
        if layer:
            out.append(layer)
    if int(aff_res.get("corrupt") or 0) >= 50:
        out.append(_CORRUPT_LAYER)
    # 压迫场（2026-11-05）：`injection_block` 判出这一场是压迫戏时，会在
    # res 里标 `forced`。这里只加**怎么写**，不加「该不该做」——那些在
    # `injection_block` 和 `writing_skills` 里已经说过了，重复三遍模型会麻木。
    if aff_res.get("forced"):
        out.append(_FORCED_LAYER)
    # 笔法层（2026-11-05，第一步）：从这里开始，除了「这一拍走到哪一步」，
    # 再按数值轴挑一小段 `skills/writing/` 的规范原文。上面几块管**节奏**，
    # 这块管**用词和肉感**——两者不重叠，所以叠在一起拼。
    # 读不到规范（文件缺失、标记被改）时 `writing_skills.guide()` 返回空串，
    # 这一轮退回只靠 `_INTIMATE_GUIDE`，不影响回话。
    try:
        spec = writing_skills.guide(aff_res)
    except Exception:                                     # noqa: BLE001
        spec = ""
        log.warning("写作规范注入失败，这一轮只用内置写法", exc_info=True)
    if spec:
        out.append(spec)
    return ("\n" + "\n".join(out)) if out else ""


