    "心里是「再近一点」。潜台词比说出口的那句重要，一个没说完的句子比十个完整句有力。\n"
    "- **句式跟着情绪走。** 三十字的长句后面接一个三到十字的短句；"
    "段落长短不齐，一段两百字、下一段十五字、再下一段八十字；"
